import Link from "next/link"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Bell, Phone, MapPin, FileText, Grid3x3, GraduationCap, Rocket, Briefcase, AlertTriangle } from "lucide-react"

export default function HomePage() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-orange-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 px-4 py-4">
        <div className="flex items-center justify-between max-w-7xl mx-auto">
          <div>
            <h1 className="text-2xl lg:text-3xl font-bold text-purple-900 leading-tight">
              Magandang umaga,
              <br />
              Calapeño!
            </h1>
          </div>
          <button className="relative p-2 rounded-full hover:bg-gray-100">
            <Bell className="w-6 h-6 text-gray-700" />
            <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full"></span>
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6 space-y-6">
        {/* What would you like to do? */}
        <section>
          <h2 className="text-lg font-semibold text-gray-900 mb-4">What would you like to do?</h2>
          <div className="grid grid-cols-4 gap-4">
            <Link
              href="/services"
              className="flex flex-col items-center gap-2 p-4 bg-orange-50 rounded-2xl hover:bg-orange-100 transition-colors"
            >
              <Grid3x3 className="w-8 h-8 text-orange-600" />
              <span className="text-sm font-medium text-gray-900">Services</span>
            </Link>
            <Link
              href="/citizen-guide"
              className="flex flex-col items-center gap-2 p-4 bg-teal-50 rounded-2xl hover:bg-teal-100 transition-colors"
            >
              <FileText className="w-8 h-8 text-teal-600" />
              <span className="text-sm font-medium text-gray-900">Citizen Guide</span>
            </Link>
            <Link
              href="/e-services"
              className="flex flex-col items-center gap-2 p-4 bg-yellow-50 rounded-2xl hover:bg-yellow-100 transition-colors"
            >
              <Grid3x3 className="w-8 h-8 text-yellow-600" />
              <span className="text-sm font-medium text-gray-900">e-Services</span>
            </Link>
            <Link
              href="/emergency"
              className="flex flex-col items-center gap-2 p-4 bg-red-50 rounded-2xl hover:bg-red-100 transition-colors"
            >
              <AlertTriangle className="w-8 h-8 text-red-600" />
              <span className="text-sm font-medium text-gray-900">Emergency</span>
            </Link>
            <Link
              href="/students"
              className="flex flex-col items-center gap-2 p-4 bg-blue-50 rounded-2xl hover:bg-blue-100 transition-colors"
            >
              <GraduationCap className="w-8 h-8 text-blue-600" />
              <span className="text-sm font-medium text-gray-900">Students</span>
            </Link>
            <Link
              href="/startup"
              className="flex flex-col items-center gap-2 p-4 bg-purple-50 rounded-2xl hover:bg-purple-100 transition-colors"
            >
              <Rocket className="w-8 h-8 text-purple-600" />
              <span className="text-sm font-medium text-gray-900">Startup</span>
            </Link>
            <Link
              href="/business"
              className="flex flex-col items-center gap-2 p-4 bg-green-50 rounded-2xl hover:bg-green-100 transition-colors"
            >
              <Briefcase className="w-8 h-8 text-green-600" />
              <span className="text-sm font-medium text-gray-900">Business</span>
            </Link>
            <Link
              href="/all-services"
              className="flex flex-col items-center gap-2 p-4 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-colors"
            >
              <Grid3x3 className="w-8 h-8 text-gray-600" />
              <span className="text-sm font-medium text-gray-900">View All</span>
            </Link>
          </div>
        </section>

        {/* Help us improve our city */}
        <Card className="bg-gradient-to-br from-purple-700 to-purple-900 border-0">
          <CardContent className="p-6 space-y-4">
            <h3 className="text-xl font-bold text-white">Help us improve our city</h3>
            <p className="text-purple-100">Spotted an issue in your area? Contact us so we can fix it together.</p>
            <div className="space-y-2">
              <Button variant="secondary" className="w-full bg-white text-purple-900 hover:bg-gray-100">
                View Reports
              </Button>
              <Button className="w-full bg-orange-500 text-white hover:bg-orange-600">Report an Issue</Button>
            </div>
          </CardContent>
        </Card>

        {/* Quick Actions */}
        <section>
          <h2 className="text-lg font-semibold text-gray-900 mb-4">Quick Actions</h2>
          <div className="space-y-3">
            <Link
              href="/emergency-call"
              className="flex items-center gap-4 p-4 bg-white rounded-xl hover:shadow-md transition-shadow"
            >
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center">
                <Phone className="w-6 h-6 text-red-600" />
              </div>
              <div>
                <h4 className="font-semibold text-gray-900">Emergency Call</h4>
                <p className="text-sm text-gray-600">One-tap emergency hotline</p>
              </div>
            </Link>
            <Link
              href="/map"
              className="flex items-center gap-4 p-4 bg-white rounded-xl hover:shadow-md transition-shadow"
            >
              <div className="w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center">
                <MapPin className="w-6 h-6 text-orange-600" />
              </div>
              <div>
                <h4 className="font-semibold text-gray-900">City Map</h4>
                <p className="text-sm text-gray-600">Find hospitals, police stations, and more</p>
              </div>
            </Link>
          </div>
        </section>
      </main>
    </div>
  )
}
